#define max_it 100
#define max_dist 10.
#define min_dist .01

float scene(vec3 p) {
    float l = max_dist;

    //l = min(l, length(fract(p) - .5) - .1);
    l = min(l, noised(p) - .1 + .5/(1. + .2*length(p)));
    l = max(l, 5. - length(p));

    return l;
}

bool march(vec3 p, vec3 d, out float lo) {
    lo = 0.;

    for (int i = 0; i < max_it && lo < max_dist; ++i) {
        float l = scene(p);

        lo += l;
        p += l * d;

        if (l < min_dist)
            return true;
    }

    return false;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord - iResolution.xy*.5) / iResolution.y;
    vec3 c = vec3(0);

    vec3 ro = get3(DATA_POS);
    vec3 rd = look_at(get3(DATA_DIR), get3(DATA_UP)) * normalize(vec3(uv, .6));

    float lo;
    if (march(ro, rd, lo)) {
        c += lo / max_dist;
    } else
        //c += smoothstep(-.5, .5, rd) * .5;
        c += 1.;

    c.xyz = pow(c.xyz, vec3(1./2.2));
    fragColor = vec4(c, 1.);

    //vec3 vv = get3(DATA_);
    //fragColor = vec4(vv, 1.);
}

bool is_coord(int data, vec2 frag_coord) {
    return data == int(frag_coord.x);
}
#define is(data) is_coord(data, fragCoord)

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec4 c = vec4(0);

    if (iFrame == 0) {
        if (is(DATA_POS))
            c.xyz = vec3(0, 0, 0);
        else if (is(DATA_DIR))
            c.xyz = vec3(0, 0, -1);
        else if (is(DATA_UP))
            c.xyz = UP;
    } else {
        if (is(DATA_POS)) {
            vec3 p = get3(DATA_POS);
            vec3 d = get3(DATA_DIR);
            float speed = .01;

            p += d * speed;
            c.xyz = p;

        } else if (is(DATA_DIR) || is(DATA_UP)) {
            vec3 d = get3(DATA_DIR);
            vec3 u = get3(DATA_UP);
            vec3 r = cross(u, d);
            vec2 m = (iMouse.xy - iResolution.xy*.5) / iResolution.y;
            m *= .05;

            if (is(DATA_DIR)) {
                d = rotateAroundAxis(d, r, m.y);
                c.xyz = d;
            } else if (is(DATA_UP)) {
                u = rotateAroundAxis(u, r, m.y);
                d = cross(r, u);
                u = rotateAroundAxis(u, d, -m.x);
                c.xyz = u;
            }
        }
    }

    fragColor = c;
}

#define DATA_POS 0
#define DATA_DIR 1
#define DATA_UP 2

#define UP vec3(0, 1, 0)

#define get3(data) \
    (texture(iChannel0, (1. / iResolution.x) * vec2(float(data)+.5, .5)).xyz)

mat3 look_at(vec3 d, vec3 u) {
    vec3 r = normalize(cross(u, d));
    return mat3(r, u, d);
}

// thanks to chatgpt
vec3 rotateAroundAxis(vec3 v, vec3 axis, float angle) {
    axis = normalize(axis); // Ensure the axis is normalized
    float cosAngle = cos(angle);
    float sinAngle = sin(angle);

    // Apply the axis-angle rotation formula
    return v * cosAngle +
           cross(axis, v) * sinAngle +
           axis * dot(axis, v) * (1.0 - cosAngle);
}

// thanks to inigo quilez: https://www.shadertoy.com/view/4dffRH
vec3 hash( ivec3 p )     // this hash is not production ready, please
{                        // replace this by something better
	ivec3 n = ivec3( p.x*127 + p.y*311 + p.z*74,
                     p.x*269 + p.y*183 + p.z*246,
                     p.x*113 + p.y*271 + p.z*124);

	// 1D hash by Hugo Elias
	n = (n << 13) ^ n;
    n = n * (n * n * 15731 + 789221) + 1376312589;
    return -1.0+2.0*vec3( n & ivec3(0x0fffffff))/float(0x0fffffff);
}
float noised( in vec3 x )
{
    // grid
    ivec3 i = ivec3(floor(x));
    vec3 f = fract(x);

    // quintic interpolant
    vec3 u = f*f*f*(f*(f*6.0-15.0)+10.0);
    vec3 du = 30.0*f*f*(f*(f-2.0)+1.0);   

    // gradients
    vec3 ga = hash( i+ivec3(0,0,0) );
    vec3 gb = hash( i+ivec3(1,0,0) );
    vec3 gc = hash( i+ivec3(0,1,0) );
    vec3 gd = hash( i+ivec3(1,1,0) );
    vec3 ge = hash( i+ivec3(0,0,1) );
	vec3 gf = hash( i+ivec3(1,0,1) );
    vec3 gg = hash( i+ivec3(0,1,1) );
    vec3 gh = hash( i+ivec3(1,1,1) );

    // projections
    float va = dot( ga, f-vec3(0.0,0.0,0.0) );
    float vb = dot( gb, f-vec3(1.0,0.0,0.0) );
    float vc = dot( gc, f-vec3(0.0,1.0,0.0) );
    float vd = dot( gd, f-vec3(1.0,1.0,0.0) );
    float ve = dot( ge, f-vec3(0.0,0.0,1.0) );
    float vf = dot( gf, f-vec3(1.0,0.0,1.0) );
    float vg = dot( gg, f-vec3(0.0,1.0,1.0) );
    float vh = dot( gh, f-vec3(1.0,1.0,1.0) );

    // interpolations
    return ( va + u.x*(vb-va) + u.y*(vc-va) + u.z*(ve-va) + u.x*u.y*(va-vb-vc+vd) + u.y*u.z*(va-vc-ve+vg) + u.z*u.x*(va-vb-ve+vf) + (-va+vb+vc-vd+ve-vf-vg+vh)*u.x*u.y*u.z);
}
